titles={'UNESCO_MELAKA':'UNESCO · Melaka and George Town','UNESCO_LENGGONG':'UNESCO · Archaeological Heritage of the Lenggong Valley','ARKIB_INDEPENDENCE':'Arkib Negara Malaysia · Dokumen Perisytiharan Kemerdekaan','MY_CUSTOMS':'Royal Malaysian Customs · Menelusuri Susur Galur Syahbandar (2022)','ASEAN_UN_TREATY':'UN Treaty Collection · ASEAN Declaration, Bangkok, 8 August 1967','NAS_CONSTITUTION':'National Archives of Singapore · Law of the Land','UNESCO_SANGIRAN':'UNESCO · Sangiran Early Man Site','SETNEG_PROCLAMATION':'Indonesia State Secretariat · Proclamation, 17 August 1945'}
src=[]
for sid,title in titles.items():
 s=sources[sid];src.append({'id':sid,'title':title,'url':s['url'],'sha256':s['sha256'],'retrievedAt':s.get('retrievedAt'),'publicationDate':'2022' if sid=='MY_CUSTOMS' else None,'verificationState':'VERIFIED_DOCUMENT_AND_CLAIM_SPANS','rightsState':'CC_BY_SA_IGO_3_0_DESCRIPTION_ONLY' if sid.startswith('UNESCO') else 'FACT_SUMMARY_LINK_ONLY_NO_TEXT_OR_MEDIA_REPUBLICATION','licenseUrl':'https://creativecommons.org/licenses/by-sa/3.0/igo/' if sid.startswith('UNESCO') else None,'excerptRepublished':False,'sourceImagesReused':False,'language':'ms' if sid in ('ARKIB_INDEPENDENCE','MY_CUSTOMS') else 'id' if sid=='SETNEG_PROCLAMATION' else 'en','sourceNature':'OFFICIAL_RETROSPECTIVE_HISTORICAL_ACCOUNT' if sid!='ASEAN_UN_TREATY' else 'OFFICIAL_TREATY_METADATA'})
def pair(z,e):return {'zh-Hans':z,'en':e}
records=[]
def add(id,country,phase,title,entity,period,scope,claim,source,cases,facets,dimensions,span):
 records.append({'id':id,'countryCode':country,'phase':phase,'title':pair(*title),'historicalEntity':entity,'period':period,'geographicScope':pair(*scope),'claim':pair(*claim),'sourceRef':source,'sourceLocation':span,'verificationState':'VERIFIED_SOURCE_BOUND','relatedCaseIds':cases,'language':['zh-Hans','en'],'rightsState':next(x['rightsState'] for x in src if x['id']==source),'facets':facets,'dimensionIds':dimensions,'modernBordersEquivalent':False,'sourceAccountNotFullCaseVerification':True})
def period(z,e,start=None,end=None):return {'label':pair(z,e),'startYear':start,'endYear':end,'approximate':True}
add('MYS-EARLY','MYS',1,('早期人类活动与考古','Early human activity and archaeology'),'Lenggong Valley archaeological sites',period('约183万至1700年前','Approximately 1.83 million to 1,700 years ago'),('今马来西亚霹雳州玲珑谷遗址；不是现代国家的起源日期','Lenggong Valley sites in present-day Perak; not the founding date of a modern country'),('UNESCO记载玲珑谷保存了跨越旧石器时代及后续时期的考古序列，可从遗址与工具阅读早期人类活动。','UNESCO describes a long sequence of archaeological remains at Lenggong, including Palaeolithic workshops. This is evidence about a locality and human activity, not a modern national identity.'),'UNESCO_LENGGONG',[],['archaeology','early'],['growth','identity'],'Outstanding Universal Value, Brief synthesis / criteria iii–iv')
add('MYS-MARITIME','MYS',2,('海洋贸易与区域联系','Maritime trade and regional connections'),'Trading ports of the Strait of Malacca',period('15世纪至殖民时期的有界资料','Bounded evidence from the 15th century through colonial periods',1400,1900),('马六甲海峡港口与东西方航线；不等于现代马来西亚全部疆域','Straits ports and East–West routes; not all present-day Malaysian territory'),('UNESCO将马六甲与乔治市的城市遗产联系到长期东西方贸易与文化往来。这为海峡港口史提供起点，不能单独证明早期区域政权的完整疆域。','UNESCO links the heritage of Melaka and George Town to sustained trade and cultural exchange. These ports provide a starting point for Straits history, without establishing the complete territory of earlier regional states.'),'UNESCO_MELAKA',['CA-T11-02','CA-T12-02'],['maritime','trade'],['relationships','growth'],'Description / Outstanding Universal Value')
add('MYS-MALACCA','MYS',3,('马六甲苏丹国与港口管理','Malacca Sultanate and port administration'),'Malacca Sultanate',period('15世纪；原图谱案例约1400–1511','15th century; Atlas context approximately 1400–1511',1400,1511),('历史马六甲港与来往商人；今马六甲仅是地点对应','Historical Melaka port and visiting merchants; present-day Melaka is a place cross-reference'),('皇家关税局的历史刊物记载，Syahbandar按商人群体分工，处理市场与仓储、度量衡、船舶出入和税务。可据此阅读港务制度；它不提供每年、每种货物或每笔交易的完整税率账簿。','The Customs Department’s historical publication describes Syahbandar assigned to merchant groups, with duties covering markets, warehouses, measures, ship movements and taxation. It supports a port-administration account, not a complete annual tariff or individual transaction ledger.'),'MY_CUSTOMS',['CA-T11-02'],['malacca','trade-system','harbourmaster'],['relationships','identity'],'PDF pages 9–10 (printed pages 8–9); selected page visually inspected')
add('MYS-COLONIAL','MYS',4,('殖民与贸易结构变化','Colonial periods and changing trade structures'),'Melaka and George Town under distinct colonial periods',period('16至19世纪的港口遗产','Port heritage from the 16th to 19th centuries',1500,1900),('马六甲与槟城两个港口；不覆盖所有殖民社会经验','Two ports, not all colonial social experience'),('UNESCO将马六甲遗产联系到葡萄牙、荷兰时期，将乔治市联系到18世纪末以来的英国时期。可以比较两港留下的不同贸易城市结构，不据此解释全部殖民影响。','UNESCO distinguishes Portuguese and Dutch layers in Melaka from the British-era townscape of George Town from the late eighteenth century. This supports a bounded comparison of port heritage, rather than a complete account of colonial effects.'),'UNESCO_MELAKA',['CA-T12-02'],['colonial'],['growth','relationships'],'Description, second paragraph')
add('MYS-INDEPENDENCE','MYS',5,('1957年马来亚联合邦独立','Federation of Malaya independence, 1957'),'Federation of Malaya',period('1957年8月31日','31 August 1957',1957,1957),('马来亚联合邦；须区别1963年成立的马来西亚','Federation of Malaya; distinct from the federation formed in 1963'),('马来西亚国家档案馆将1957年8月31日的独立宣言与马来亚联合邦联系起来；这与1963年马来西亚成立是不同历史事项。','The National Archives identifies the independence proclamation of 31 August 1957 with the Federation of Malaya. It is distinct from the formation of Malaysia in 1963.'),'ARKIB_INDEPENDENCE',['CA-T16-06'],['independence','1957'],['identity','growth'],'Paragraphs introducing the proclamation and distinguishing 1957 / 1963')
add('MYS-FORMATION','MYS',5,('1963年马来西亚成立','Formation of Malaysia, 1963'),'Malaysia formation',period('1963年9月16日','16 September 1963',1963,1963),('1963年成立事件；不能把当前国界回溯所有时期','The 1963 formation event; current borders cannot be projected backwards'),('国家档案馆明确区分马来亚独立与1963年9月16日马来西亚成立。国家名称、当时参与地区与今日疆域必须按各自时期阅读。','The National Archives distinguishes Malayan independence from Malaysia’s formation on 16 September 1963. Names, participating territories and present borders require period-specific treatment.'),'ARKIB_INDEPENDENCE',['CA-T16-06'],['formation','1963'],['identity','relationships'],'Paragraph stating formation of Malaysia on 16 September 1963')
for code in ['MYS','SGP','IDN']:
 add(code+'-REGIONAL',code,6,('1967年的区域合作起点','Regional cooperation in 1967'),'ASEAN Declaration',period('1967年8月8日','8 August 1967',1967,1967),('东南亚多国合作；不等于单一国家的发展成效','Multistate Southeast Asian cooperation; not a national development outcome'),('联合国条约登记记载，马来西亚、新加坡与印度尼西亚均于1967年8月8日签署成立东盟的宣言。这提供区域联系史的一个节点；国内发展过程与成效仍需其他资料。','The UN treaty record lists Malaysia, Singapore and Indonesia as signatories on 8 August 1967 to the declaration establishing ASEAN. This is a regional-history milestone, not proof of domestic development outcomes.'),'ASEAN_UN_TREATY',['CA-T16-06'],['asean','regional'],['relationships','growth'],'Treaty 22341, title, conclusion date and participant signature table')
add('SGP-CONSTITUTION','SGP',4,('1819–1965年的宪制资料路径','Constitutional records, 1819–1965'),'Singapore constitutional development',period('1819–1965','1819–1965',1819,1965),('新加坡岛的宪制资料路径；新加坡历史不始于1819年','An island constitutional-history path; Singapore history did not begin in 1819'),('新加坡国家档案馆通过宪制文件介绍1819年至1965年的制度变迁，包括殖民阶段与共和国建立。此路径不代替更早历史或完整社会史。','Singapore’s National Archives presents constitutional documents spanning 1819–1965, covering colonial institutional changes and the emergence of a republic. This is not a substitute for earlier history or a complete social history.'),'NAS_CONSTITUTION',[],['constitution','colonial'],['identity','growth'],'About the Exhibition / constitutional document headings')
add('SGP-INDEPENDENCE','SGP',5,('1965年共和国宣告','Republic proclamation, 1965'),'Republic of Singapore',period('1965年8月9日','9 August 1965',1965,1965),('共和国宣告事件；区别1963年的马来西亚成立','Republic proclamation; distinct from Malaysia’s 1963 formation'),('新加坡国家档案馆列出1965年8月9日的共和国宣告文件，可从该文书继续阅读国家形成过程。','The National Archives of Singapore lists the Proclamation of the Republic of Singapore dated 9 August 1965, providing a document-led path into state formation.'),'NAS_CONSTITUTION',['CA-T16-06'],['independence','1965'],['identity'],'Proclamation of the Republic of Singapore – 9 August 1965')
add('IDN-EARLY','IDN',1,('桑义兰早期人类遗址','Sangiran early human site'),'Sangiran archaeological site',period('史前考古记录','Prehistoric archaeological record'),('今印度尼西亚爪哇的桑义兰遗址；不是国家成立日期','Sangiran in present-day Java; not the founding date of a nation'),('UNESCO将桑义兰列为理解早期人类的重要化石遗址。遗址考古与现代印度尼西亚国家形成属于不同时间尺度。','UNESCO identifies Sangiran as a major fossil site for understanding early humans. Archaeology at this locality and the formation of modern Indonesia belong to different timescales.'),'UNESCO_SANGIRAN',[],['archaeology','early'],['identity','growth'],'Description')
add('IDN-INDEPENDENCE','IDN',5,('1945年的独立宣言','Independence proclamation, 1945'),'Indonesian independence proclamation',period('1945年8月17日','17 August 1945',1945,1945),('雅加达的独立宣告；不据此推断后续全部主权与发展过程','The Jakarta proclamation; not the entire subsequent sovereignty or development process'),('印度尼西亚国家秘书处记述1945年8月17日的独立宣言准备与宣告。其后主权承认、地方经历及发展变化需要分别检索。','Indonesia’s State Secretariat recounts the preparation and proclamation of independence on 17 August 1945. Subsequent recognition, local experiences and development require separate sources.'),'SETNEG_PROCLAMATION',['CA-T16-06'],['independence','1945'],['identity','growth'],'Article chronology for 17 August 1945')
